import{_ as e,c as a,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1785925329000}'),r={name:"guide/introduction.md"};function n(l,t,s,c,d,u){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="about-clipboard-x-ai" tabindex="-1">About Clipboard x AI <a class="header-anchor" href="#about-clipboard-x-ai" aria-label="Permalink to &quot;About Clipboard x AI&quot;">​</a></h2><p><strong>Clipboard x AI</strong> is a smart clipboard manager for macOS. Every time you copy text, code, or a link, it&#39;s saved to a searchable history in your menu bar. With one click — or completely automatically — you can run an action on that clip: summarize it, translate it, tidy it up, or hand it to a cloud AI model.</p><p>It is built around two kinds of tools:</p><ul><li><strong>Built-in local tools</strong> that run entirely on your Mac, with no network connection.</li><li><strong>AI actions</strong> that call a cloud model you configure yourself (your own API key, stored in the system Keychain).</li></ul><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="📋-clipboard-history" tabindex="-1">📋 Clipboard History <a class="header-anchor" href="#📋-clipboard-history" aria-label="Permalink to &quot;📋 Clipboard History&quot;">​</a></h3><p>Everything you copy is captured automatically and kept in a searchable history. Jump back to any previous clip from the menu bar — no more lost snippets.</p><h3 id="⚡-smart-suggestions" tabindex="-1">⚡ Smart Suggestions <a class="header-anchor" href="#⚡-smart-suggestions" aria-label="Permalink to &quot;⚡ Smart Suggestions&quot;">​</a></h3><p>Clipboard x AI suggests the most relevant actions for the current clip. Accept a suggestion, or browse the full list of tools.</p><h3 id="🛠️-built-in-local-tools" tabindex="-1">🛠️ Built-in Local Tools <a class="header-anchor" href="#🛠️-built-in-local-tools" aria-label="Permalink to &quot;🛠️ Built-in Local Tools&quot;">​</a></h3><p>Offline, private, instant:</p><ul><li><strong>Extract Links</strong> — pull every URL out of a block of text.</li><li><strong>Count Stats</strong> — word, character, line and sentence counts.</li><li><strong>Collapse Blank Lines</strong> — tidy up pasted text in one step.</li></ul><p>More local tools can be added over time — they never leave your device.</p><h3 id="✨-ai-actions" tabindex="-1">✨ AI Actions <a class="header-anchor" href="#✨-ai-actions" aria-label="Permalink to &quot;✨ AI Actions&quot;">​</a></h3><p>Send the current clip to a cloud model to:</p><ul><li><strong>Summarize</strong> long articles and threads.</li><li><strong>Translate</strong> between languages.</li><li><strong>Rewrite / polish</strong> tone and clarity.</li><li>Run any action from the <strong>Marketplace</strong>.</li></ul><h3 id="🛒-action-marketplace" tabindex="-1">🛒 Action Marketplace <a class="header-anchor" href="#🛒-action-marketplace" aria-label="Permalink to &quot;🛒 Action Marketplace&quot;">​</a></h3><p>Browse community-made AI actions and install them in one click via a deep link (<code>clipboardxai://install?action=&lt;id&gt;</code>). Categories include Writing, Developer, Productivity, Translate, Social, and Analytics.</p><h3 id="🔒-private-by-design" tabindex="-1">🔒 Private by Design <a class="header-anchor" href="#🔒-private-by-design" aria-label="Permalink to &quot;🔒 Private by Design&quot;">​</a></h3><p>Your clipboard history stays on your device. Cloud AI is <strong>opt-in</strong>: when enabled, content is sent only to the provider <em>you</em> choose, using an API key stored in your Keychain. We never receive or store your clips, and there is no analytics or telemetry.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li><strong>Operating System</strong>: macOS 14 Sonoma or later</li><li><strong>CPU</strong>: Apple Silicon (M-series) or Intel (64-bit)</li><li><strong>Memory</strong>: 4 GB RAM minimum, 8 GB recommended</li><li><strong>Storage</strong>: ~50 MB for installation</li><li><strong>For cloud AI</strong>: an API key from a supported provider (DeepSeek, MiniMax, Zhipu GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic, or Gemini)</li></ul><h2 id="supported-languages" tabindex="-1">Supported Languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to &quot;Supported Languages&quot;">​</a></h2><p>The app and this site support English, 简体中文 (Simplified Chinese), 繁體中文 (Traditional Chinese), and 日本語 (Japanese).</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>If you&#39;re new to Clipboard x AI, start with the <a href="/guide/installation.html">Installation Guide</a> to get the app running on your Mac, then read <a href="/guide/usage.html">Usage</a> to learn how actions work.</p>',27)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
